        d[r['conta']]=float(r['debito'])-float(r['credito'])
    return d
jan=load_bal('mes_01/balancete.csv'); fev=load_bal('mes_02/balancete.csv')
mov={}
for r in csv.DictReader(open('mes_02/razao.csv')):
    m=mov.setdefault(r['conta'],[0.0,0.0])
    m[0]+=float(r['debito'] or 0); m[1]+=float(r['credito'] or 0)
bad=0
for k in sorted(set(jan)|set(mov)|set(fev)):
    net=mov.get(k,[0,0]); calc=jan.get(k,0)+net[0]-net[1]
    if abs(calc-fev.get(k,0))>=0.01:
        bad+=1; print("DIVERGE",k,"calc",calc,"balancete",fev.get(k))
print("Divergências:", bad, "de", len(set(jan)|set(mov)|set(fev)), "contas")
# saldo devedor agregado do balancete fev (quebras D x C)
print("Checagem adicional: razão fev bate em D e C?", 
      sum(v[0] for v in mov.values())==sum(v[1] for v in mov.values()))
EOF

